  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਅਧਾਰ 'ਤੇ ਇੱਕ ਨੌਜਵਾਨ ਦੇ ਆਪਣੇ ਪਿੰਡ ਪ੍ਰਤੀ ਫਰਜ਼ਾਂ ਬਾਰੇ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬਾਬਾ ਗੁਰਦੇਵ ਸਿੰਘ ਜੀ ਨੇ ਲਵਪ੍ਰੀਤ ਨੂੰ ਵਿਦੇਸ਼ ਜਾਣ ਦੀ ਬਜਾਏ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਰਹਿ ਕੇ ਤਰੱਕੀ ਕਰਨ ਲਈ ਕਿਵੇਂ ਪ੍ਰੇਰਿਤ ਕੀਤਾ? ਵਿਸਥਾਰ ਸਹਿਤ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ ਦੇ ਕਿਰਦਾਰ ਵਿੱਚ ਕੀ ਤਬਦੀਲੀ ਆਈ ਅਤੇ ਇਸ ਤਬਦੀਲੀ ਦੇ ਕੀ ਕਾਰਨ ਸਨ? ਪਾਠ ਦੇ ਆਧਾਰ 'ਤੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$'ਆਪਣੀਆਂ ਜੜ੍ਹਾਂ ਨਾਲ ਜੁੜੇ ਰਹਿਣਾ' ਤੋਂ ਕੀ ਭਾਵ ਹੈ? ਪਾਠ ਦੇ ਪ੍ਰਸੰਗ ਵਿੱਚ ਇਸਦੀ ਮਹੱਤਤਾ ਬਾਰੇ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦੇਸ਼ ਭਗਤੀ ਅਤੇ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਰਹਿ ਕੇ ਤਰੱਕੀ ਕਰਨ ਦੇ ਸੰਦੇਸ਼ ਨੂੰ ਕਿਵੇਂ ਉਭਾਰਿਆ ਗਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨਕੀਰਤ, ਲਵਪ੍ਰੀਤ ਅਤੇ ਬਾਬਾ ਗੁਰਦੇਵ ਸਿੰਘ ਜੀ ਦੇ ਵਿਚਾਰਾਂ ਦੀ ਤੁਲਨਾ ਕਰੋ ਅਤੇ ਦੱਸੋ ਕਿ ਉਹ ਕਿਵੇਂ ਇੱਕ ਦੂਜੇ ਤੋਂ ਵੱਖਰੇ ਹਨ ਜਾਂ ਸਮਾਨ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ ਦੇ ਮਾਪਿਆਂ (ਗੁਰਮੁਖ ਸਿੰਘ ਜੀ) ਦਾ ਆਪਣੇ ਪੁੱਤਰ ਦੇ ਫੈਸਲੇ ਪ੍ਰਤੀ ਕੀ ਰਵੱਈਆ ਸੀ? ਇਸ ਤੋਂ ਸਾਨੂੰ ਕੀ ਸਿੱਖਿਆ ਮਿਲਦੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
