  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ 'ਸ਼ੁਹਰਤ ਅਤੇ ਪੈਸਾ' ਕਮਾਉਣ ਬਾਰੇ ਕੀ ਕਿਹਾ ਗਿਆ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੀ ਕਹਾਣੀ ਨੂੰ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਸੰਖੇਪ ਵਿੱਚ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਨਾਮ ਕੌਰ ਦੀਆਂ ਭਾਵਨਾਵਾਂ ਅਤੇ ਉਸਦੇ ਪੁੱਤਰ ਲਵਪ੍ਰੀਤ ਪ੍ਰਤੀ ਉਸਦੇ ਪਿਆਰ ਦਾ ਵਿਸਥਾਰਪੂਰਵਕ ਵਰਣਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦ੍ਰਿਸ਼ 4 “ਸਮਝੌਤਾ ਤੇ ਇਕੱਠ” ਦੇ ਸਿਰਲੇਖ ਦੀ ਸਾਰਥਕਤਾ ਦੀ ਵਿਆਖਿਆ ਕਰੋ। ਇਸ ਦ੍ਰਿਸ਼ ਵਿੱਚ ਕੀ ਸਮਝੌਤਾ ਹੁੰਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
