  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨਕੀਰਤ ਦੇ ਕਿਰਦਾਰ ਦੀ ਵਿਸ਼ੇਸ਼ਤਾ ਦੱਸੋ। ਉਸਨੇ ਲਵਪ੍ਰੀਤ ਦੇ ਨਜ਼ਰੀਏ ਨੂੰ ਬਦਲਣ ਵਿੱਚ ਕਿਵੇਂ ਮਦਦ ਕੀਤੀ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$“ਵਿਦੇਸ਼ ਜਾਣ ਦੀ ਦੌੜ ਨੇ ਮੈਨੂੰ ਕੀਲ ਲਿਆ ਸੀ” - ਇਸ ਕਥਨ ਦਾ ਭਾਵ ਸਪਸ਼ਟ ਕਰੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਅੱਜ ਦੇ ਸਮਾਜ ਵਿੱਚ ਕਿੰਨਾ ਕੁ ਪ੍ਰਸੰਗਿਕ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$“ਮਿੱਟੀ ਨਾਲ ਜੁੜੇ ਰਹਿਣਾ ਵੀ ਲਾਜ਼ਮੀ ਹੈ” - ਇਸ ਵਾਕ ਦੇ ਡੂੰਘੇ ਅਰਥਾਂ ਦੀ ਵਿਆਖਿਆ ਕਰੋ ਅਤੇ ਦੱਸੋ ਕਿ ਇਹ ਕਿਸ ਤਰ੍ਹਾਂ ਦੇਸ਼ ਭਗਤੀ ਨਾਲ ਸੰਬੰਧਿਤ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਿੱਤੇ ਗਏ ਸਿੱਖਣ ਨਤੀਜਿਆਂ ਦੀ ਵਿਸਥਾਰਪੂਰਵਕ ਵਿਆਖਿਆ ਕਰੋ। ਇਹ ਨਤੀਜੇ ਵਿਦਿਆਰਥੀਆਂ ਲਈ ਕਿਉਂ ਮਹੱਤਵਪੂਰਨ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$N.E.P. ਅਤੇ N.C.F. ਦੇ ਨਿਰਦੇਸ਼ਾਂ 'ਤੇ ਆਧਾਰਿਤ ਹੋਣ ਦਾ ਕੀ ਮਤਲਬ ਹੈ? ਇਹ ਪਾਠ ਵਿਦਿਆਰਥੀਆਂ ਦੀ ਸਮਝ ਨੂੰ ਕਿਵੇਂ ਪਰਖਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਅੰਤ ਵਿੱਚ ਪੁੱਛੇ ਗਏ ਪ੍ਰਸ਼ਨ “ਤੁਸੀਂ ਕੀ ਸੋਚਦੇ ਹੋ - ਵਿਦੇਸ਼ ਜਾਣਾ ਹਮੇਸ਼ਾ ਹੀ ਚੰਗਾ ਹੈ ਜਾਂ ਸਥਾਨਕ ਮੌਕੇ ਵੀ ਮਹੱਤਵਪੂਰਨ ਹਨ?” 'ਤੇ ਆਪਣੀ ਰਾਏ ਵਿਸਥਾਰ ਨਾਲ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
