  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਦਰਸਾਏ ਗਏ ਮਾਤਾ-ਪਿਤਾ ਅਤੇ ਬੱਚੇ ਦੇ ਰਿਸ਼ਤੇ ਬਾਰੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ ਦੇ ਮਨ ਵਿੱਚ ਵਿਦੇਸ਼ ਜਾਣ ਬਾਰੇ ਪਹਿਲਾਂ ਕੀ ਵਿਚਾਰ ਸਨ ਅਤੇ ਉਹ ਕਿਵੇਂ ਬਦਲੇ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$“ਬੱਸ ਨਜ਼ਰੀਆ ਬਦਲਣ ਦੀ ਲੋੜ ਹੈ” - ਇਸ ਕਥਨ ਦੀ ਰੋਸ਼ਨੀ ਵਿੱਚ ਪਾਠ ਦੇ ਮੁੱਖ ਵਿਸ਼ੇ ਦੀ ਵਿਆਖਿਆ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ ਵਰਤੇ ਗਏ ਸੰਵਾਦ (ਡਾਇਲਾਗ) ਸ਼ੈਲੀ ਦੀ ਪ੍ਰਭਾਵਸ਼ੀਲਤਾ ਬਾਰੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਪਾਠ ਤੋਂ ਤੁਸੀਂ ਆਪਣੇ ਜੀਵਨ ਲਈ ਕਿਹੜੀਆਂ ਸਿੱਖਿਆਵਾਂ ਪ੍ਰਾਪਤ ਕਰਦੇ ਹੋ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਦੇ ਅੰਤ ਵਿੱਚ ਦੋਸਤਾਂ ਦੀ ਖੁਸ਼ੀ ਦਾ ਕੀ ਕਾਰਨ ਸੀ? ਇਸ ਖੁਸ਼ੀ ਦਾ ਕੀ ਮਹੱਤਵ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$“ਦੂਜਿਆਂ ਦੀ ਨਕਲ ਕਰ ਕੇ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਜਾਣ ਦੀ ਹੋੜ ਤੋਂ ਬਚਣ ਦੀ ਪ੍ਰੇਰਨਾ ਦਾ ਵਿਕਾਸ” - ਇਸ ਸਿੱਖਣ ਨਤੀਜੇ ਦੀ ਸਮਾਜਿਕ ਪ੍ਰਸੰਗਿਕਤਾ ਬਾਰੇ ਲਿਖੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ “ਤਰੱਕੀ ਦੇ ਮੌਕੇ” ਬਾਰੇ ਕੀ ਦੱਸਿਆ ਗਿਆ ਹੈ? ਕੀ ਇਹ ਸਿਰਫ਼ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਹੀ ਉਪਲਬਧ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ ਦੇ ਮਾਤਾ-ਪਿਤਾ ਦੀ ਚਿੰਤਾ ਅਤੇ ਬਾਅਦ ਵਿੱਚ ਖੁਸ਼ੀ ਨੂੰ ਵਿਸਥਾਰ ਨਾਲ ਬਿਆਨ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਨਾਟਕੀ ਅੰਸ਼ ਤੋਂ ਸਾਨੂੰ ਕਿਹੜੇ ਸਮਾਜਿਕ ਮੁੱਲਾਂ ਬਾਰੇ ਪਤਾ ਲੱਗਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ “ਸਾਧਨ ਮੁੱਕ ਜਾਣ” ਦੀ ਗੱਲ ਕਿਸ ਸੰਦਰਭ ਵਿੱਚ ਕੀਤੀ ਗਈ ਹੈ? ਕੀ ਇਹ ਹਮੇਸ਼ਾ ਸੱਚ ਹੁੰਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ “ਸਮਝ ਦੀ ਪਰਖ” ਕਿਵੇਂ ਕੀਤੀ ਗਈ ਹੈ? ਇਸਦੇ ਕੀ ਲਾਭ ਹਨ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ ਅਤੇ ਮਨਕੀਰਤ ਦੀ ਦੋਸਤੀ ਇਸ ਪਾਠ ਵਿੱਚ ਕਿਵੇਂ ਉਭਰ ਕੇ ਸਾਹਮਣੇ ਆਉਂਦੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਠ ਵਿੱਚ “ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਰਹਿ ਕੇ ਰੁਜ਼ਗਾਰ ਦੇ ਮੌਕੇ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਯਤਨਸ਼ੀਲ ਹੋਣਾ” ਦੇ ਮਹੱਤਵ ਬਾਰੇ ਚਰਚਾ ਕਰੋ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇਸ ਪਾਠ ਨੂੰ ਪੜ੍ਹਨ ਤੋਂ ਬਾਅਦ ਵਿਦਿਆਰਥੀਆਂ ਦੇ ਨਜ਼ਰੀਏ ਵਿੱਚ ਕੀ ਬਦਲਾਅ ਆ ਸਕਦਾ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true);
INSERT INTO public.question_bank (id, institution_id, subject_id, topic_id, grade_level_id, class_group_id, question_text, question_type, options, correct_answer, marks, difficulty_level, tags, source, created_by, is_approved, parent_question_id, sub_question_count, sequence_order) VALUES
  ('68a17ecb-b361-4c4d-a982-848a9177d8e2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਰੁਜ਼ਗਾਰ ਦੀ ਭਾਲ ਦੀ ਥਾਂ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਹੀ ਰੁਜ਼ਗਾਰ ਦਾ ਉੱਦਮ ਕਰਨ ਦੀ ਭਾਵਨਾ ਦਾ ਵਿਕਾਸ ਕਰਨਾ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('992b2bbb-7b8a-47a5-91b1-3f71c2d83677', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਾਤਰ— ਲਵਪ੍ਰੀਤ - ਚੁਸਤ ਅਤੇ ਉੱਚੀ ਸੋਚ ਵਾਲਾ ਵਿਦਿਆਰਥੀ, ਜੋ ਵਿਦੇਸ਼ ਜਾਣ ਦੇ ਸੁਪਨੇ ਵੇਖਦਾ ਹੈ। ਮਨਕੀਰਤ - ਗੰਭੀਰ ਅਤੇ ਵਿਚਾਰਸ਼ੀਲ ਦੋਸਤ ਜੋ ਪਿੰਡ ਵਿੱਚ ਰਹਿ ਕੇ ਮਿਹਨਤ ਕਰਨਾ ਚਾਹੁੰਦਾ ਹੈ। ਬਾਬਾ ਗੁਰਦੇਵ ਸਿੰਘ - ਪਿੰਡ ਦੇ ਬਜ਼ੁਰਗ ਮਾਸਟਰ ਜੀ। ਗੁਰਮੁਖ ਸਿੰਘ - ਲਵਪ੍ਰੀਤ ਦਾ ਪਿਤਾ ਤੇ ਪਿੰਡ ਦਾ ਸੁਧਾਰਨ ਇਨਸਾਨ। ਹਰਨਾਮ ਕੌਰ - ਲਵਪ੍ਰੀਤ ਦੀ ਮਾਂ, ਜੋ ਪੁੱਤਰ ਦੇ ਭਵਿੱਖ ਦੀ ਚਿੰਤਾ ਕਰਦੀ ਹੈ। ਸਮੂਹ ਵਿਦਿਆਰਥੀ - ਜੋ ਵੱਖ-ਵੱਖ ਵਿਚਾਰ ਰੱਖਦੇ ਹਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e3d7baaf-3bc1-4b98-bdd6-21ecc1996355', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦ੍ਰਿਸ਼ A. ਸਕੂਲ ਦਾ ਵਿਹੜਾ - ਚਰਚਾ ਅਤੇ ਤਣਾਅ ਬਾਰ੍ਹਵੀਂ ਜਮਾਤ ਨੂੰ ਅੱਧੀ ਛੁੱਟੀ ਹੋਈ ਸੀ। ਸਕੂਲ ਦੇ ਵਿਹੜੇ ਵਿੱਚ ਬੱਚੇ ਨਿੱਕੀਆਂ-ਨਿੱਕੀਆਂ ਢਾਣੀਆਂ ਵਿੱਚ ਖੜ੍ਹੇ ਗੱਲਾਂ ਕਰ ਰਹੇ ਸਨ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('95ac7519-d268-468e-92b0-626220dec287', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ ਉਤਸ਼ਾਹ ਨਾਲ ਦੋਸਤਾਂ ਨੂੰ ਆਪਣੇ IELTS ਪਾਸ ਕਰਨ ਬਾਰੇ ਦੱਸ ਰਿਹਾ ਹੈ। ਲਵਪ੍ਰੀਤ (ਉਤਸ਼ਾਹ ਨਾਲ) - ਦੋਸਤੋ! ਮੈਂ IELTS ਦਾ ਪੇਪਰ ਸੱਤ ਬੈਂਡ ਨਾਲ ਪਾਸ ਕਰ ਲਿਆ ਹੈ। ਹੁਣ ਮੇਰਾ ਕੈਨੇਡਾ ਜਾਣ ਦਾ ਸੁਪਨਾ ਪੂਰਾ ਹੋ ਜਾਣਾ। ਇੰਜ ਫੁਰਰ ਕਰਕੇ ਉੱਡ ਜਾਣਾ ਮੈਂ ਕੈਨੇਡਾ। ਫਿਰ ਕਰਾਂਗਾ ਆਪਣੇ ਸੁਪਨੇ ਪੂਰੇ। ਇੱਥੇ ਤਾਂ ਰੁਜ਼ਗਾਰ ਦੇ ਕੋਈ ਵੱਡੇ ਮੌਕੇ ਹੀ ਨਹੀਂ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c76a9d68-04b7-424c-8ec8-f9baffb2b255', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨਕੀਰਤ (ਹੌਲੀ ਤੇ ਗੰਭੀਰ ਆਵਾਜ਼ ਵਿੱਚ) - ਲਵਪ੍ਰੀਤ ਤੂੰ ਆਪਣਾ ਭਵਿੱਖ ਸੰਵਾਰਨਾ ਚਾਹੁੰਦਾ ਹੈਂ। ਇਹ ਚੰਗੀ ਗੱਲ ਹੈ ਪਰ ਕੀ ਇਹ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਸੰਵਾਰਿਆ ਜਾ ਸਕਦਾ ਹੈ? ਵਿਦੇਸ਼ ਜਾਣਾ ਇੱਕ ਰਾਹ ਹੈ, ਪਰ ਉਹ ਇੱਕੋ ਰਾਹ ਨਹੀਂ। ਇੱਥੇ ਵੀ ਮਿਹਨਤ ਨਾਲ ਬਹੁਤ ਕੁਝ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
