  ('b81b98a4-ff03-4e2a-b1a5-011725586e9e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੇਰੁਜ਼ਗਾਰੀ, ਭ੍ਰਿਸ਼ਟਾਚਾਰ ਅਤੇ ਹਰ ਮੋੜ 'ਤੇ ਤੁਹਾਡਾ ਸ਼ੋਸ਼ਣ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('6c84c879-8dde-4272-a01e-9c688051e4d3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੱਚ ਆ, ਇੱਥੇ ਤਾਂ ਸਾਡਾ ਭਵਿੱਖ ਧੁੰਦਲਾ ਹੀ ਲੱਗਦੈ। ਨੌਕਰੀ ਇੱਕ ਨਿੱਕੀ ਜਿਹੀ ਤੇ ਲਾਈਨ ਹਜ਼ਾਰਾਂ ਦੀ। (ਉੱਚੀ ਆਵਾਜ਼ ਵਿੱਚ) ਹਾਂ ਯਾਰ, ਹੁਣ ਤਾਂ ਸਾਰੇ ਬਾਹਰ ਜਾ ਕੇ ਹੀ ਸੈੱਟ ਹੋ ਰਹੇ ਨੇ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('a2cfd337-1d95-4d31-bf62-83f5e3bacd61', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਾਡੇ ਕੋਲ ਆਪਣੀ ਮਿੱਟੀ ਹੈ, ਆਪਣੇ ਪਰਿਵਾਰ ਹਨ। ਇੱਥੇ ਮਿਹਨਤ ਕਰ ਕੇ ਵੀ ਸਭ ਕੁਝ ਮਿਲ ਸਕਦਾ ਹੈ। ਮੇਰੇ ਪਿੰਡ ਦੇ ਕੁਝ ਉੱਦਮੀ ਨੌਜਵਾਨਾਂ ਨੇ ਇੱਥੇ ਰਹਿ ਕੇ ਹੀ ਚੰਗਾ ਕਾਰੋਬਾਰ ਸ਼ੁਰੂ ਕੀਤਾ ਤੇ ਨਾਲੇ ਪਿੰਡ ਦਾ ਮੂੰਹ-ਮੱਥਾ ਵੀ ਸੰਵਾਰ ਰਹੇ ਹਨ। ਤੁਸੀਂ ਆਓ! ਸਾਰੇ ਕੱਲ੍ਹ ਐਤਵਾਰ ਨੂੰ ਸਾਡੇ ਪਿੰਡ। ਨਾਲੇ ਆਪ ਹੀ ਫੈਸਲਾ ਕਰਿਓ ਕਿ ਸਹੀ ਕੀ ਹੈ?$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('04e80056-666c-4569-b397-92ebd30a6d57', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜੀ ਆਇਆਂ ਨੂੰ ਦੋਸਤੋ! ਇਹ ਮੇਰਾ ਪਿੰਡ ਹੈ। ਅੱਜ ਮੈਂ ਤੁਹਾਨੂੰ ਪਿੰਡ ਵਿੱਚ ਰਹਿ ਕੇ ਡਰੈਗਨ ਫਰੂਟ ਦੀ ਖੇਤੀ ਅਤੇ ਸ਼ੁੱਧ ਦੇਸੀ ਘਿਓ ਦੀ ਲਾਈ ਇੰਡਸਟਰੀ ਤੋਂ ਲੱਖਾਂ ਰੁਪਏ ਕਮਾਉਣ ਵਾਲੇ ਨੌਜਵਾਨਾਂ ਨਾਲ ਮਿਲਾਉਂਦਾ ਹਾਂ। (ਮਨਕੀਰਤ ਦੋਸਤਾਂ ਨੂੰ ਪਿੰਡ ਦੇ ਉੱਦਮੀ ਨੌਜਵਾਨਾਂ ਨਾਲ ਮਿਲਾ ਕੇ ਉਹਨਾਂ ਦੇ ਕਾਰੋਬਾਰ ਦਿਖਾਉਂਦਾ ਹੈ।)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
