  ('bfdbcbfd-aa6c-445a-b26b-73cc97e637c3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes) ਸਮਝ ਦੀ ਪਰਖ (ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ ਉੱਤੇ ਆਧਾਰਿਤ) (Think & Express) A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ੁਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਓ— (ੳ) ਤੁਸੀਂ ਕੀ ਸੋਚਦੇ ਹੋ - ਵਿਦੇਸ਼ ਜਾਣਾ ਹਮੇਸ਼ਾ ਹੀ ਚੰਗਾ ਹੈ ਜਾਂ ਸਥਾਨਕ ਮੌਕੇ ਵੀ ਮਹੱਤਵਪੂਰਨ ਹਨ? ਆਪਣੀ ਰਾਏ ਦੱਸੋ। ਨਜ਼ਰੀਆ - ਸੋਚ/ਵਿਚਾਰਧਾਰਾ (perspective)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
