  ('d265d816-0255-458c-86a4-71734c1daf54', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$(ਪਰਦਾ ਡਿੱਗਦਾ ਹੈ। ਸਾਰੇ ਦੋਸਤ ਖੁਸ਼ੀ-ਖੁਸ਼ੀ ਗੱਲਾਂ ਕਰਦੇ ਹਨ। * ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਰਹਿ ਕੇ ਰੁਜ਼ਗਾਰ ਦੇ ਮੌਕੇ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਯਤਨਸ਼ੀਲ ਹੋਣਾ।)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('9633062a-a7da-46e5-b5d2-0d817d0675c8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$* ਦੂਜਿਆਂ ਦੀ ਨਕਲ ਕਰ ਕੇ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਜਾਣ ਦੀ ਹੋੜ ਤੋਂ ਬਚਣ ਦੀ ਪ੍ਰੇਰਨਾ ਦਾ ਵਿਕਾਸ। ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes) ਸਮਝ ਦੀ ਪਰਖ (ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ ਉੱਤੇ ਆਧਾਰਿਤ)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('44432c43-bc2c-47ca-90fc-75e1d2a738eb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$(Think & Express) A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ੁਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਓ— (ੳ) ਤੁਸੀਂ ਕੀ ਸੋਚਦੇ ਹੋ - ਵਿਦੇਸ਼ ਜਾਣਾ ਹਮੇਸ਼ਾ ਹੀ ਚੰਗਾ ਹੈ ਜਾਂ ਸਥਾਨਕ ਮੌਕੇ ਵੀ ਮਹੱਤਵਪੂਰਨ ਹਨ? ਆਪਣੀ ਰਾਏ ਦੱਸੋ। ਨਜ਼ਰੀਆ - ਸੋਚ/ਵਿਚਾਰਧਾਰਾ (perspective)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('13adc7fe-0767-46da-8436-3af60f979c47', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਨਾਮ ਕੌਰ (ਖੁਸ਼ੀ ਵਿੱਚ) - ਮੈਂ ਸਦਕੇ ਆਪਣੇ ਪੁੱਤ ਦੀ ਸੋਚ ਦੇ। ਮੈਂ ਤਾਂ ਤੇਰੇ ਵਿਦੇਸ਼ ਜਾਣ ਬਾਰੇ ਸੋਚ ਕੇ ਰੋਜ਼ ਸੋਚਦੀ ਰਹਿੰਦੀ ਸੀ ਕਿ ਤੇਰਾ ਵਿਯੋਗ ਕਿਵੇਂ ਝੱਲਿਆ ਕਰਾਂਗੀ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ddfaeb0e-1d45-4519-a56d-14c8d5d1a36b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸ਼ਾਬਾਸ਼! ਮੇਰਾ ਸੋਹਣਾ ਪੁੱਤਰ। ਮੈਂ ਹੁਣੇ ਤੇਰੇ ਲਈ ਚੂਰੀ ਕੁੱਟ ਕੇ ਲਿਆਉਂਦੀ ਹਾਂ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('b1461ba6-d98b-49c7-a67e-ce79eabd99b3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$(ਗੁਰਮੁਖ ਸਿੰਘ ਅਤੇ ਹਰਨਾਮ ਕੌਰ ਅੱਖਾਂ ਪੂੰਝਦੇ ਲਵਪ੍ਰੀਤ ਨੂੰ ਘੁੱਟ ਕੇ ਜੱਫੀ ਪਾ ਲੈਂਦੇ ਹਨ। ਦ੍ਰਿਸ਼ 4. ਅੰਤ - ਸਮਝੌਤਾ ਤੇ ਇਕੱਠ)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('7673775a-1247-4fca-b70c-67df73362f5c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$(ਦੋਸਤ ਇਕੱਠੇ ਹੋ ਕੇ ਸਮਝਦੇ ਹਨ ਕਿ ਦੋਹਾਂ ਵਿਚਾਰਾਂ ਵਿੱਚ ਸੱਚਾਈ ਹੈ। ਵਿਦੇਸ਼ ਜਾਣ ਦੇ ਸੁਪਨੇ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਵੀ ਤਰੱਕੀ ਦੇ ਮੌਕੇ ਹਨ। ਲਵਪ੍ਰੀਤ — ਮਨਕੀਰਤ ਤੂੰ ਸਹੀ ਕਹਿੰਦਾ ਸੀ ਯਾਰ, ਆਪਣੇ ਮੁਲਕ ਵਿੱਚ ਵੀ ਸਭ ਕੁਝ ਹੈ।)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0ed2e172-3e59-4460-abf4-f8eddfd8a903', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੱਸ ਨਜ਼ਰੀਆ ਬਦਲਣ ਦੀ ਲੋੜ ਹੈ। ਵਿਦੇਸ਼ ਜਾਣ ਦੀ ਦੌੜ ਨੇ ਮੈਨੂੰ ਕੀਲ ਲਿਆ ਸੀ। ਮਨਕੀਰਤ - ਲਵਪ੍ਰੀਤ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਭਵਿੱਖ ਬਣਾਉਣਾ ਮਾੜਾ ਨਹੀਂ, ਪਰ ਉਦੋਂ ਜਦੋਂ ਇੱਥੇ ਸਾਰੇ ਸਾਧਨ ਮੁੱਕ ਜਾਣ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('71325e59-3479-4fc3-8b06-fc9c5073b8d5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਆਖਰਕਾਰ ਮਿੱਟੀ ਨਾਲ ਜੁੜੇ ਰਹਿਣਾ ਵੀ ਲਾਜ਼ਮੀ ਹੈ। ਲਵਪ੍ਰੀਤ - ਧੰਨਵਾਦ ਮਨਕੀਰਤ, ਤੇਰੇ ਕੀਤੇ ਉੱਦਮ ਨੇ ਮੇਰਾ ਨਜ਼ਰੀਆ ਬਦਲ ਦਿੱਤਾ। (ਪਰਦਾ ਡਿੱਗਦਾ ਹੈ।)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('dd8cce32-abc2-4fc3-a1c6-99e2269c96f0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਾਰੇ ਦੋਸਤ ਖੁਸ਼ੀ-ਖੁਸ਼ੀ ਗੱਲਾਂ ਕਰਦੇ ਹਨ। * ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਰਹਿ ਕੇ ਰੁਜ਼ਗਾਰ ਦੇ ਮੌਕੇ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਯਤਨਸ਼ੀਲ ਹੋਣਾ। * ਦੂਜਿਆਂ ਦੀ ਨਕਲ ਕਰ ਕੇ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਜਾਣ ਦੀ ਹੋੜ ਤੋਂ ਬਚਣ ਦੀ ਪ੍ਰੇਰਨਾ ਦਾ ਵਿਕਾਸ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('10082709-b062-4734-aeae-97a25710bc77', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes) ਸਮਝ ਦੀ ਪਰਖ (ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ ਉੱਤੇ ਆਧਾਰਿਤ) (Think & Express) A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ੁਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਓ—$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('aa306242-e28f-4f5f-ae33-8fca100e01d8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$(ੳ) ਤੁਸੀਂ ਕੀ ਸੋਚਦੇ ਹੋ - ਵਿਦੇਸ਼ ਜਾਣਾ ਹਮੇਸ਼ਾ ਹੀ ਚੰਗਾ ਹੈ ਜਾਂ ਸਥਾਨਕ ਮੌਕੇ ਵੀ ਮਹੱਤਵਪੂਰਨ ਹਨ? ਆਪਣੀ ਰਾਏ ਦੱਸੋ। ਨਜ਼ਰੀਆ - ਸੋਚ/ਵਿਚਾਰਧਾਰਾ (perspective)$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('6ba22605-7901-47ff-bd1d-a494c7f1078b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਰੁਜ਼ਗਾਰ ਦੀ ਭਾਲ ਦੀ ਥਾਂ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਹੀ ਰੁਜ਼ਗਾਰ ਦਾ ਉੱਦਮ ਕਰਨ ਦੀ ਭਾਵਨਾ ਦਾ ਵਿਕਾਸ ਕਰਨਾ। ਪਾਤਰ— ਲਵਪ੍ਰੀਤ - ਚੁਸਤ ਅਤੇ ਉੱਚੀ ਸੋਚ ਵਾਲਾ ਵਿਦਿਆਰਥੀ, ਜੋ ਵਿਦੇਸ਼ ਜਾਣ ਦੇ ਸੁਪਨੇ ਵੇਖਦਾ ਹੈ। ਮਨਕੀਰਤ - ਗੰਭੀਰ ਅਤੇ ਵਿਚਾਰਸ਼ੀਲ ਦੋਸਤ ਜੋ ਪਿੰਡ ਵਿੱਚ ਰਹਿ ਕੇ ਮਿਹਨਤ ਕਰਨਾ ਚਾਹੁੰਦਾ ਹੈ। ਬਾਬਾ ਗੁਰਦੇਵ ਸਿੰਘ - ਪਿੰਡ ਦੇ ਬਜ਼ੁਰਗ ਮਾਸਟਰ ਜੀ। ਗੁਰਮੁਖ ਸਿੰਘ - ਲਵਪ੍ਰੀਤ ਦਾ ਪਿਤਾ ਤੇ ਪਿੰਡ ਦਾ ਸੁਧਾਰਨ ਇਨਸਾਨ। ਹਰਨਾਮ ਕੌਰ - ਲਵਪ੍ਰੀਤ ਦੀ ਮਾਂ, ਜੋ ਪੁੱਤਰ ਦੇ ਭਵਿੱਖ ਦੀ ਚਿੰਤਾ ਕਰਦੀ ਹੈ। ਸਮੂਹ ਵਿਦਿਆਰਥੀ - ਜੋ ਵੱਖ-ਵੱਖ ਵਿਚਾਰ ਰੱਖਦੇ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('62cb6b32-d595-4e19-b98e-558a0efded1d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦ੍ਰਿਸ਼ A. ਸਕੂਲ ਦਾ ਵਿਹੜਾ - ਚਰਚਾ ਅਤੇ ਤਣਾਅ ਬਾਰ੍ਹਵੀਂ ਜਮਾਤ ਨੂੰ ਅੱਧੀ ਛੁੱਟੀ ਹੋਈ ਸੀ। ਸਕੂਲ ਦੇ ਵਿਹੜੇ ਵਿੱਚ ਬੱਚੇ ਨਿੱਕੀਆਂ-ਨਿੱਕੀਆਂ ਢਾਣੀਆਂ ਵਿੱਚ ਖੜ੍ਹੇ ਗੱਲਾਂ ਕਰ ਰਹੇ ਸਨ। ਲਵਪ੍ਰੀਤ ਉਤਸ਼ਾਹ ਨਾਲ ਦੋਸਤਾਂ ਨੂੰ ਆਪਣੇ IELTS ਪਾਸ ਕਰਨ ਬਾਰੇ ਦੱਸ ਰਿਹਾ ਹੈ। ਲਵਪ੍ਰੀਤ (ਉਤਸ਼ਾਹ ਨਾਲ) - ਦੋਸਤੋ! ਮੈਂ IELTS ਦਾ ਪੇਪਰ ਸੱਤ ਬੈਂਡ ਨਾਲ ਪਾਸ ਕਰ ਲਿਆ ਹੈ। ਹੁਣ ਮੇਰਾ ਕੈਨੇਡਾ ਜਾਣ ਦਾ ਸੁਪਨਾ ਪੂਰਾ ਹੋ ਜਾਣਾ। ਇੰਜ ਫੁਰਰ ਕਰਕੇ ਉੱਡ ਜਾਣਾ ਮੈਂ ਕੈਨੇਡਾ। ਫਿਰ ਕਰਾਂਗਾ ਆਪਣੇ ਸੁਪਨੇ ਪੂਰੇ। ਇੱਥੇ ਤਾਂ ਰੁਜ਼ਗਾਰ ਦੇ ਕੋਈ ਵੱਡੇ ਮੌਕੇ ਹੀ ਨਹੀਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0b30050e-81e8-437e-8e68-a0c2275f9751', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨਕੀਰਤ (ਹੌਲੀ ਤੇ ਗੰਭੀਰ ਆਵਾਜ਼ ਵਿੱਚ) - ਲਵਪ੍ਰੀਤ ਤੂੰ ਆਪਣਾ ਭਵਿੱਖ ਸੰਵਾਰਨਾ ਚਾਹੁੰਦਾ ਹੈਂ। ਇਹ ਚੰਗੀ ਗੱਲ ਹੈ ਪਰ ਕੀ ਇਹ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਸੰਵਾਰਿਆ ਜਾ ਸਕਦਾ ਹੈ? ਵਿਦੇਸ਼ ਜਾਣਾ ਇੱਕ ਰਾਹ ਹੈ, ਪਰ ਉਹ ਇੱਕੋ ਰਾਹ ਨਹੀਂ। ਇੱਥੇ ਵੀ ਮਿਹਨਤ ਨਾਲ ਬਹੁਤ ਕੁਝ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ। ਲਵਪ੍ਰੀਤ (ਤਿੱਖੀ ਆਵਾਜ਼ ਵਿੱਚ) - ਮਨਕੀਰਤ ਤੂੰ ਭੋਲੀਆਂ ਗੱਲਾਂ ਕਰਦਾ ਹੈਂ। ਇੱਥੇ ਕੀ ਹੈ? ਬੇਰੁਜ਼ਗਾਰੀ, ਭ੍ਰਿਸ਼ਟਾਚਾਰ ਅਤੇ ਹਰ ਮੋੜ 'ਤੇ ਤੁਹਾਡਾ ਸ਼ੋਸ਼ਣ। ਜਿੱਥੇ ਤਕਨੀਕੀ ਅਤੇ ਮੌਕਿਆਂ ਦੀ ਕਮੀ ਹੋਵੇ, ਉੱਥੇ ਅੱਗੇ ਵਧਣਾ ਮੁਸ਼ਕਲ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ad2d60dd-3e0a-47ac-935a-f79d37f02fd5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਰੁਜ਼ਗਾਰ ਦੀ ਭਾਲ ਦੀ ਥਾਂ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਹੀ ਰੁਜ਼ਗਾਰ ਦਾ ਉੱਦਮ ਕਰਨ ਦੀ ਭਾਵਨਾ ਦਾ ਵਿਕਾਸ ਕਰਨਾ। ਪਾਤਰ— ਲਵਪ੍ਰੀਤ - ਚੁਸਤ ਅਤੇ ਉੱਚੀ ਸੋਚ ਵਾਲਾ ਵਿਦਿਆਰਥੀ, ਜੋ ਵਿਦੇਸ਼ ਜਾਣ ਦੇ ਸੁਪਨੇ ਵੇਖਦਾ ਹੈ। ਮਨਕੀਰਤ - ਗੰਭੀਰ ਅਤੇ ਵਿਚਾਰਸ਼ੀਲ ਦੋਸਤ ਜੋ ਪਿੰਡ ਵਿੱਚ ਰਹਿ ਕੇ ਮਿਹਨਤ ਕਰਨਾ ਚਾਹੁੰਦਾ ਹੈ। ਬਾਬਾ ਗੁਰਦੇਵ ਸਿੰਘ - ਪਿੰਡ ਦੇ ਬਜ਼ੁਰਗ ਮਾਸਟਰ ਜੀ। ਗੁਰਮੁਖ ਸਿੰਘ - ਲਵਪ੍ਰੀਤ ਦਾ ਪਿਤਾ ਤੇ ਪਿੰਡ ਦਾ ਸੁਧਾਰਨ ਇਨਸਾਨ। ਹਰਨਾਮ ਕੌਰ - ਲਵਪ੍ਰੀਤ ਦੀ ਮਾਂ, ਜੋ ਪੁੱਤਰ ਦੇ ਭਵਿੱਖ ਦੀ ਚਿੰਤਾ ਕਰਦੀ ਹੈ। ਸਮੂਹ ਵਿਦਿਆਰਥੀ - ਜੋ ਵੱਖ-ਵੱਖ ਵਿਚਾਰ ਰੱਖਦੇ ਹਨ। ਦ੍ਰਿਸ਼ A. ਸਕੂਲ ਦਾ ਵਿਹੜਾ - ਚਰਚਾ ਅਤੇ ਤਣਾਅ ਬਾਰ੍ਹਵੀਂ ਜਮਾਤ ਨੂੰ ਅੱਧੀ ਛੁੱਟੀ ਹੋਈ ਸੀ। ਸਕੂਲ ਦੇ ਵਿਹੜੇ ਵਿੱਚ ਬੱਚੇ ਨਿੱਕੀਆਂ-ਨਿੱਕੀਆਂ ਢਾਣੀਆਂ ਵਿੱਚ ਖੜ੍ਹੇ ਗੱਲਾਂ ਕਰ ਰਹੇ ਸਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('ba452b3f-0531-4e29-a412-214167c841f8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ (ਉਤਸ਼ਾਹ ਨਾਲ) - ਦੋਸਤੋ! ਮੈਂ IELTS ਦਾ ਪੇਪਰ ਸੱਤ ਬੈਂਡ ਨਾਲ ਪਾਸ ਕਰ ਲਿਆ ਹੈ। ਹੁਣ ਮੇਰਾ ਕੈਨੇਡਾ ਜਾਣ ਦਾ ਸੁਪਨਾ ਪੂਰਾ ਹੋ ਜਾਣਾ। ਇੰਜ ਫੁਰਰ ਕਰਕੇ ਉੱਡ ਜਾਣਾ ਮੈਂ ਕੈਨੇਡਾ। ਫਿਰ ਕਰਾਂਗਾ ਆਪਣੇ ਸੁਪਨੇ ਪੂਰੇ। ਇੱਥੇ ਤਾਂ ਰੁਜ਼ਗਾਰ ਦੇ ਕੋਈ ਵੱਡੇ ਮੌਕੇ ਹੀ ਨਹੀਂ। ਮਨਕੀਰਤ (ਹੌਲੀ ਤੇ ਗੰਭੀਰ ਆਵਾਜ਼ ਵਿੱਚ) - ਲਵਪ੍ਰੀਤ ਤੂੰ ਆਪਣਾ ਭਵਿੱਖ ਸੰਵਾਰਨਾ ਚਾਹੁੰਦਾ ਹੈਂ। ਇਹ ਚੰਗੀ ਗੱਲ ਹੈ ਪਰ ਕੀ ਇਹ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਸੰਵਾਰਿਆ ਜਾ ਸਕਦਾ ਹੈ? ਵਿਦੇਸ਼ ਜਾਣਾ ਇੱਕ ਰਾਹ ਹੈ, ਪਰ ਉਹ ਇੱਕੋ ਰਾਹ ਨਹੀਂ। ਇੱਥੇ ਵੀ ਮਿਹਨਤ ਨਾਲ ਬਹੁਤ ਕੁਝ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('c4381e6a-f155-4ca6-ba3b-4ec822a6bbcf', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ (ਤਿੱਖੀ ਆਵਾਜ਼ ਵਿੱਚ) - ਮਨਕੀਰਤ ਤੂੰ ਭੋਲੀਆਂ ਗੱਲਾਂ ਕਰਦਾ ਹੈਂ। ਇੱਥੇ ਕੀ ਹੈ? ਬੇਰੁਜ਼ਗਾਰੀ, ਭ੍ਰਿਸ਼ਟਾਚਾਰ ਅਤੇ ਹਰ ਮੋੜ 'ਤੇ ਤੁਹਾਡਾ ਸ਼ੋਸ਼ਣ। ਜਿੱਥੇ ਤਕਨੀਕੀ ਅਤੇ ਮੌਕਿਆਂ ਦੀ ਕਮੀ ਹੋਵੇ, ਉੱਥੇ ਅੱਗੇ ਵਧਣਾ ਮੁਸ਼ਕਲ ਹੈ। ਉਤਸ਼ਾਹ - ਜੋਸ਼ (excitement), ਵਿਦੇਸ਼ - ਹੋਰ ਦੇਸ਼ (foreign country), ਭ੍ਰਿਸ਼ਟਾਚਾਰ - ਬੇਈਮਾਨੀ, ਗਲਤ ਢੰਗ ਨਾਲ ਕਮਾਈ ਕਰਨੀ (corruption)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1c6f753a-8b91-4a05-82a7-dc516b531251', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੁੱਖ ਵਿਚਾਰ (Key Concept) ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਰੁਜ਼ਗਾਰ ਦੀ ਭਾਲ ਦੀ ਥਾਂ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਹੀ ਰੁਜ਼ਗਾਰ ਦਾ ਉੱਦਮ ਕਰਨ ਦੀ ਭਾਵਨਾ ਦਾ ਵਿਕਾਸ ਕਰਨਾ। ਪਾਤਰ— ਲਵਪ੍ਰੀਤ - ਚੁਸਤ ਅਤੇ ਉੱਚੀ ਸੋਚ ਵਾਲਾ ਵਿਦਿਆਰਥੀ, ਜੋ ਵਿਦੇਸ਼ ਜਾਣ ਦੇ ਸੁਪਨੇ ਵੇਖਦਾ ਹੈ। ਮਨਕੀਰਤ - ਗੰਭੀਰ ਅਤੇ ਵਿਚਾਰਸ਼ੀਲ ਦੋਸਤ ਜੋ ਪਿੰਡ ਵਿੱਚ ਰਹਿ ਕੇ ਮਿਹਨਤ ਕਰਨਾ ਚਾਹੁੰਦਾ ਹੈ। ਬਾਬਾ ਗੁਰਦੇਵ ਸਿੰਘ - ਪਿੰਡ ਦੇ ਬਜ਼ੁਰਗ ਮਾਸਟਰ ਜੀ। ਗੁਰਮੁਖ ਸਿੰਘ - ਲਵਪ੍ਰੀਤ ਦਾ ਪਿਤਾ ਤੇ ਪਿੰਡ ਦਾ ਸੁਧਾਰਨ ਇਨਸਾਨ। ਹਰਨਾਮ ਕੌਰ - ਲਵਪ੍ਰੀਤ ਦੀ ਮਾਂ, ਜੋ ਪੁੱਤਰ ਦੇ ਭਵਿੱਖ ਦੀ ਚਿੰਤਾ ਕਰਦੀ ਹੈ। ਸਮੂਹ ਵਿਦਿਆਰਥੀ - ਜੋ ਵੱਖ-ਵੱਖ ਵਿਚਾਰ ਰੱਖਦੇ ਹਨ। ਦ੍ਰਿਸ਼ A. ਸਕੂਲ ਦਾ ਵਿਹੜਾ - ਚਰਚਾ ਅਤੇ ਤਣਾਅ ਬਾਰ੍ਹਵੀਂ ਜਮਾਤ ਨੂੰ ਅੱਧੀ ਛੁੱਟੀ ਹੋਈ ਸੀ। ਸਕੂਲ ਦੇ ਵਿਹੜੇ ਵਿੱਚ ਬੱਚੇ ਨਿੱਕੀਆਂ-ਨਿੱਕੀਆਂ ਢਾਣੀਆਂ ਵਿੱਚ ਖੜ੍ਹੇ ਗੱਲਾਂ ਕਰ ਰਹੇ ਸਨ। ਲਵਪ੍ਰੀਤ ਉਤਸ਼ਾਹ ਨਾਲ ਦੋਸਤਾਂ ਨੂੰ ਆਪਣੇ IELTS ਪਾਸ ਕਰਨ ਬਾਰੇ ਦੱਸ ਰਿਹਾ ਹੈ। ਲਵਪ੍ਰੀਤ (ਉਤਸ਼ਾਹ ਨਾਲ) - ਦੋਸਤੋ! ਮੈਂ IELTS ਦਾ ਪੇਪਰ ਸੱਤ ਬੈਂਡ ਨਾਲ ਪਾਸ ਕਰ ਲਿਆ ਹੈ। ਹੁਣ ਮੇਰਾ ਕੈਨੇਡਾ ਜਾਣ ਦਾ ਸੁਪਨਾ ਪੂਰਾ ਹੋ ਜਾਣਾ। ਇੰਜ ਫੁਰਰ ਕਰਕੇ ਉੱਡ ਜਾਣਾ ਮੈਂ ਕੈਨੇਡਾ। ਫਿਰ ਕਰਾਂਗਾ ਆਪਣੇ ਸੁਪਨੇ ਪੂਰੇ। ਇੱਥੇ ਤਾਂ ਰੁਜ਼ਗਾਰ ਦੇ ਕੋਈ ਵੱਡੇ ਮੌਕੇ ਹੀ ਨਹੀਂ। ਮਨਕੀਰਤ (ਹੌਲੀ ਤੇ ਗੰਭੀਰ ਆਵਾਜ਼ ਵਿੱਚ) - ਲਵਪ੍ਰੀਤ ਤੂੰ ਆਪਣਾ ਭਵਿੱਖ ਸੰਵਾਰਨਾ ਚਾਹੁੰਦਾ ਹੈਂ। ਇਹ ਚੰਗੀ ਗੱਲ ਹੈ ਪਰ ਕੀ ਇਹ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਸੰਵਾਰਿਆ ਜਾ ਸਕਦਾ ਹੈ? ਵਿਦੇਸ਼ ਜਾਣਾ ਇੱਕ ਰਾਹ ਹੈ, ਪਰ ਉਹ ਇੱਕੋ ਰਾਹ ਨਹੀਂ। ਇੱਥੇ ਵੀ ਮਿਹਨਤ ਨਾਲ ਬਹੁਤ ਕੁਝ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ। ਲਵਪ੍ਰੀਤ (ਤਿੱਖੀ ਆਵਾਜ਼ ਵਿੱਚ) - ਮਨਕੀਰਤ ਤੂੰ ਭੋਲੀਆਂ ਗੱਲਾਂ ਕਰਦਾ ਹੈਂ। ਇੱਥੇ ਕੀ ਹੈ? ਬੇਰੁਜ਼ਗਾਰੀ, ਭ੍ਰਿਸ਼ਟਾਚਾਰ ਅਤੇ ਹਰ ਮੋੜ 'ਤੇ ਤੁਹਾਡਾ ਸ਼ੋਸ਼ਣ। ਜਿੱਥੇ ਤਕਨੀਕੀ ਅਤੇ ਮੌਕਿਆਂ ਦੀ ਕਮੀ ਹੋਵੇ, ਉੱਥੇ ਅੱਗੇ ਵਧਣਾ ਮੁਸ਼ਕਲ ਹੈ। ਉਤਸ਼ਾਹ - ਜੋਸ਼ (excitement), ਵਿਦੇਸ਼ - ਹੋਰ ਦੇਸ਼ (foreign country), ਭ੍ਰਿਸ਼ਟਾਚਾਰ - ਬੇਈਮਾਨੀ, ਗਲਤ ਢੰਗ ਨਾਲ ਕਮਾਈ ਕਰਨੀ (corruption)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
