  ('9eeee3e9-641d-4965-90b7-6135d10e913a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ ਉਤਸ਼ਾਹ ਨਾਲ ਦੋਸਤਾਂ ਨੂੰ ਆਪਣੇ IELTS ਪਾਸ ਕਰਨ ਬਾਰੇ ਦੱਸ ਰਿਹਾ ਹੈ। ਲਵਪ੍ਰੀਤ (ਉਤਸ਼ਾਹ ਨਾਲ) - ਦੋਸਤੋ! ਮੈਂ IELTS ਦਾ ਪੇਪਰ ਸੱਤ ਬੈਂਡ ਨਾਲ ਪਾਸ ਕਰ ਲਿਆ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
