  ('7b78fd42-1bf9-4bc6-b6c9-12cc237cf8e3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਥੇ ਤਾਂ ਰੁਜ਼ਗਾਰ ਦੇ ਕੋਈ ਵੱਡੇ ਮੌਕੇ ਹੀ ਨਹੀਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('af234605-93c9-4eb8-96eb-5a8f6277b19f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨਕੀਰਤ (ਹੌਲੀ ਤੇ ਗੰਭੀਰ ਆਵਾਜ਼ ਵਿੱਚ) - ਲਵਪ੍ਰੀਤ ਤੂੰ ਆਪਣਾ ਭਵਿੱਖ ਸੰਵਾਰਨਾ ਚਾਹੁੰਦਾ ਹੈਂ। ਇਹ ਚੰਗੀ ਗੱਲ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('cc85b5a4-c089-4135-9eb6-33dd43770648', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਪਰ ਕੀ ਇਹ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਸੰਵਾਰਿਆ ਜਾ ਸਕਦਾ ਹੈ? ਵਿਦੇਸ਼ ਜਾਣਾ ਇੱਕ ਰਾਹ ਹੈ, ਪਰ ਉਹ ਇੱਕੋ ਰਾਹ ਨਹੀਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('d83d0a70-8b24-48ae-991b-10a0e835a3b0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਇੱਥੇ ਵੀ ਮਿਹਨਤ ਨਾਲ ਬਹੁਤ ਕੁਝ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('fea299b8-f93c-4b39-add4-ee535f4690e0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ (ਤਿੱਖੀ ਆਵਾਜ਼ ਵਿੱਚ) - ਮਨਕੀਰਤ ਤੂੰ ਭੋਲੀਆਂ ਗੱਲਾਂ ਕਰਦਾ ਹੈਂ। ਇੱਥੇ ਕੀ ਹੈ?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('f2e748d4-fde9-4646-a617-2de93813269d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਬੇਰੁਜ਼ਗਾਰੀ, ਭ੍ਰਿਸ਼ਟਾਚਾਰ ਅਤੇ ਹਰ ਮੋੜ 'ਤੇ ਤੁਹਾਡਾ ਸ਼ੋਸ਼ਣ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('5188d8ed-3d3b-4fd7-b68a-23d8a37219bf', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਜਿੱਥੇ ਤਕਨੀਕੀ ਅਤੇ ਮੌਕਿਆਂ ਦੀ ਕਮੀ ਹੋਵੇ, ਉੱਥੇ ਅੱਗੇ ਵਧਣਾ ਮੁਸ਼ਕਲ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('809ba789-9d26-4f88-9073-0a5e8749b586', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਉਤਸ਼ਾਹ - ਜੋਸ਼ (excitement), ਵਿਦੇਸ਼ - ਹੋਰ ਦੇਸ਼ (foreign country)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('d1413aad-624e-4cf3-89a4-ea36b5ebf0a8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਭ੍ਰਿਸ਼ਟਾਚਾਰ - ਬੇਈਮਾਨੀ, ਗਲਤ ਢੰਗ ਨਾਲ ਕਮਾਈ ਕਰਨੀ (corruption)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('ae8f24a0-15c7-4cdb-a6d6-8ff7f7574116', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸੱਚ ਆ, ਇੱਥੇ ਤਾਂ ਸਾਡਾ ਭਵਿੱਖ ਧੁੰਦਲਾ ਹੀ ਲੱਗਦੈ। ਨੌਕਰੀ ਇੱਕ ਨਿੱਕੀ ਜਿਹੀ ਤੇ ਲਾਈਨ ਹਜ਼ਾਰਾਂ ਦੀ। ਜਮਾਤੀ B - (ਉੱਚੀ ਆਵਾਜ਼ ਵਿੱਚ) ਹਾਂ ਯਾਰ, ਹੁਣ ਤਾਂ ਸਾਰੇ ਬਾਹਰ ਜਾ ਕੇ ਹੀ ਸੈੱਟ ਹੋ ਰਹੇ ਨੇ। ਮਨਕੀਰਤ (ਨਿਰਾਸ਼ ਹੋ ਕੇ)- ਸਾਡੇ ਕੋਲ ਆਪਣੀ ਮਿੱਟੀ ਹੈ, ਆਪਣੇ ਪਰਿਵਾਰ ਹਨ। ਇੱਥੇ ਮਿਹਨਤ ਕਰ ਕੇ ਵੀ ਸਭ ਕੁਝ ਮਿਲ ਸਕਦਾ ਹੈ। ਮੇਰੇ ਪਿੰਡ ਦੇ ਕੁਝ ਉੱਦਮੀ ਨੌਜਵਾਨਾਂ ਨੇ ਇੱਥੇ ਰਹਿ ਕੇ ਹੀ ਚੰਗਾ ਕਾਰੋਬਾਰ ਸ਼ੁਰੂ ਕੀਤਾ ਤੇ ਨਾਲੇ ਪਿੰਡ ਦਾ ਮੂੰਹ-ਮੱਥਾ ਵੀ ਸੰਵਾਰ ਰਹੇ ਹਨ। ਤੁਸੀਂ ਆਓ! ਸਾਰੇ ਕੱਲ੍ਹ ਐਤਵਾਰ ਨੂੰ ਸਾਡੇ ਪਿੰਡ। ਨਾਲੇ ਆਪ ਹੀ ਫੈਸਲਾ ਕਰਿਓ ਕਿ ਸਹੀ ਕੀ ਹੈ? (ਲਵਪ੍ਰੀਤ ਅਤੇ ਮਨਕੀਰਤ ਨੂੰ ਆਪਣੇ ਵਿਚਕਾਰ ਤਣਾਅ ਮਹਿਸੂਸ ਹੁੰਦਾ ਹੈ।) ਦ੍ਰਿਸ਼ B. ਮਨਕੀਰਤ ਦਾ ਪਿੰਡ (ਸਵੇਰ ਦਾ ਸਮਾਂ। ਐਤਵਾਰ ਨੂੰ ਲਵਪ੍ਰੀਤ ਆਪਣੇ ਕੁਝ ਦੋਸਤਾਂ ਨਾਲ ਮਨਕੀਰਤ ਦੇ ਪਿੰਡ ਜਾਂਦਾ ਹੈ।) ਮਨਕੀਰਤ (ਮੁਸਕਰਾਉਂਦੇ ਹੋਏ)- ਜੀ ਆਇਆਂ ਨੂੰ ਦੋਸਤੋ! ਇਹ ਮੇਰਾ ਪਿੰਡ ਹੈ। ਅੱਜ ਮੈਂ ਤੁਹਾਨੂੰ ਪਿੰਡ ਵਿੱਚ ਰਹਿ ਕੇ ਡਰੈਗਨ ਫਰੂਟ ਦੀ ਖੇਤੀ ਅਤੇ ਸ਼ੁੱਧ ਦੇਸੀ ਘਿਓ ਦੀ ਲਾਈ ਇੰਡਸਟਰੀ ਤੋਂ ਲੱਖਾਂ ਰੁਪਏ ਕਮਾਉਣ ਵਾਲੇ ਨੌਜਵਾਨਾਂ ਨਾਲ ਮਿਲਾਉਂਦਾ ਹਾਂ। (ਮਨਕੀਰਤ ਦੋਸਤਾਂ ਨੂੰ ਪਿੰਡ ਦੇ ਉੱਦਮੀ ਨੌਜਵਾਨਾਂ ਨਾਲ ਮਿਲਾ ਕੇ ਉਹਨਾਂ ਦੇ ਕਾਰੋਬਾਰ ਦਿਖਾਉਂਦਾ ਹੈ।) ਲਵਪ੍ਰੀਤ (ਹੈਰਾਨੀ ਨਾਲ) - ਵਾਹ! ਇਹ ਤਾਂ ਪਿੰਡ ਵਿੱਚ ਹੀ ਹਰ ਤਰ੍ਹਾਂ ਦੀ ਤਕਨਾਲੋਜੀ ਨੂੰ ਵਿਕਸਿਤ ਕਰ ਰਹੇ ਹਨ। ਆਧੁਨਿਕ ਬੀਜ ਤੇ ਨਵੀਆਂ ਮਸ਼ੀਨਾਂ ਨਾਲ ਹਰ ਕੰਮ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ। ਮਨਕੀਰਤ - ਇਸ ਦੇ ਨਾਲ-ਨਾਲ ਕੁਦਰਤੀ ਸੁੰਦਰਤਾ ਨਾਲ ਭਰਿਆ ਹੋਇਆ ਹੈ ਮੇਰਾ ਪਿੰਡ। ਅਹੋ ਵੇਖੋ ਲਹਿਲਹਾਉਂਦੀਆਂ ਫਸਲਾਂ, ਕਲ-ਕਲ ਵਗਦਾ ਪਾਣੀ ਤੇ ਪੰਛੀਆਂ ਦੇ ਨਗਮੇ। ਲਵਪ੍ਰੀਤ (ਹੈਰਾਨ ਹੁੰਦਿਆਂ ਹੋਇਆ) - ਸੱਚੀ ਯਾਰ ਮਨਕੀਰਤ, ਇਹ ਕੁਦਰਤੀ ਨਜ਼ਾਰਾ ਕਿੰਨਾ ਸ਼ਾਂਤ ਤੇ ਖੂਬਸੂਰਤ ਹੈ। ਇੱਥੇ ਕੁਦਰਤ ਵੀ ਵੱਸਦੀ ਹੈ ਤੇ ਉੱਦਮ ਵੀ। ਸਹਿਮਤ - ਰਜ਼ਾਮੰਦ (agree), ਉੱਦਮੀ - ਕਾਰੋਬਾਰ ਕਰਨ ਵਾਲਾ (emrepreneur)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 25, NULL),
  ('a3f534ac-c6d3-4fff-9bc5-0de3a4c7ec1d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨਕੀਰਤ - ਇਹੋ ਸਾਡੀਆਂ ਜੜ੍ਹਾਂ ਹਨ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('597fe97d-2eac-449b-9aab-f2753edea014', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਕਈ ਵਾਰ ਵਿਦੇਸ਼ ਦੇ ਸੁਪਨੇ ਬੁਣਦੇ ਅਸੀਂ ਇਹ ਭੁੱਲ ਜਾਂਦੇ ਹਾਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
