  ('f4e8caaa-2c6c-4530-bebc-9994ab74fa55', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਅਤੇ ਫਿਰ ਆਪਣੇ ਕਾਰੋਬਾਰ ਜਾਂ ਨੌਕਰੀ ਕਰਨ ਬਾਰੇ ਅੰਤਿਮ ਫੈਸਲਾ ਲਵਾਂਗਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('db350945-9455-4319-add2-4cb8bc79f674', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਨਾਮ ਕੌਰ (ਖੁਸ਼ੀ ਵਿੱਚ) - ਮੈਂ ਸਦਕੇ ਆਪਣੇ ਪੁੱਤ ਦੀ ਸੋਚ ਦੇ। ਮੈਂ ਤਾਂ ਤੇਰੇ ਵਿਦੇਸ਼ ਜਾਣ ਬਾਰੇ ਸੋਚ ਕੇ ਰੋਜ਼ ਸੋਚਦੀ ਰਹਿੰਦੀ ਸੀ ਕਿ ਤੇਰਾ ਵਿਯੋਗ ਕਿਵੇਂ ਝੱਲਿਆ ਕਰਾਂਗੀ। ਸ਼ਾਬਾਸ਼! ਮੇਰਾ ਸੋਹਣਾ ਪੁੱਤਰ। ਮੈਂ ਹੁਣੇ ਤੇਰੇ ਲਈ ਚੂਰੀ ਕੁੱਟ ਕੇ ਲਿਆਉਂਦੀ ਹਾਂ। (ਗੁਰਮੁਖ ਸਿੰਘ ਅਤੇ ਹਰਨਾਮ ਕੌਰ ਅੱਖਾਂ ਪੂੰਝਦੇ ਲਵਪ੍ਰੀਤ ਨੂੰ ਘੁੱਟ ਕੇ ਜੱਫੀ ਪਾ ਲੈਂਦੇ ਹਨ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('cbf2f959-b152-430c-8954-5c51b8adc655', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦ੍ਰਿਸ਼ 4. ਅੰਤ - ਸਮਝੌਤਾ ਤੇ ਇਕੱਠ (ਦੋਸਤ ਇਕੱਠੇ ਹੋ ਕੇ ਸਮਝਦੇ ਹਨ ਕਿ ਦੋਹਾਂ ਵਿਚਾਰਾਂ ਵਿੱਚ ਸੱਚਾਈ ਹੈ। ਵਿਦੇਸ਼ ਜਾਣ ਦੇ ਸੁਪਨੇ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਵੀ ਤਰੱਕੀ ਦੇ ਮੌਕੇ ਹਨ। ਲਵਪ੍ਰੀਤ — ਮਨਕੀਰਤ ਤੂੰ ਸਹੀ ਕਹਿੰਦਾ ਸੀ ਯਾਰ, ਆਪਣੇ ਮੁਲਕ ਵਿੱਚ ਵੀ ਸਭ ਕੁਝ ਹੈ। ਬੱਸ ਨਜ਼ਰੀਆ ਬਦਲਣ ਦੀ ਲੋੜ ਹੈ। ਵਿਦੇਸ਼ ਜਾਣ ਦੀ ਦੌੜ ਨੇ ਮੈਨੂੰ ਕੀਲ ਲਿਆ ਸੀ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('a8342c4d-81af-4aba-9e19-0aab741a55bc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨਕੀਰਤ - ਲਵਪ੍ਰੀਤ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਭਵਿੱਖ ਬਣਾਉਣਾ ਮਾੜਾ ਨਹੀਂ, ਪਰ ਉਦੋਂ ਜਦੋਂ ਇੱਥੇ ਸਾਰੇ ਸਾਧਨ ਮੁੱਕ ਜਾਣ। ਆਖਰਕਾਰ ਮਿੱਟੀ ਨਾਲ ਜੁੜੇ ਰਹਿਣਾ ਵੀ ਲਾਜ਼ਮੀ ਹੈ। ਲਵਪ੍ਰੀਤ - ਧੰਨਵਾਦ ਮਨਕੀਰਤ, ਤੇਰੇ ਕੀਤੇ ਉੱਦਮ ਨੇ ਮੇਰਾ ਨਜ਼ਰੀਆ ਬਦਲ ਦਿੱਤਾ। (ਪਰਦਾ ਡਿੱਗਦਾ ਹੈ। ਸਾਰੇ ਦੋਸਤ ਖੁਸ਼ੀ-ਖੁਸ਼ੀ ਗੱਲਾਂ ਕਰਦੇ ਹਨ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('906b33eb-6c44-4e73-aa54-ade31e6fcaa5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$* ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਰਹਿ ਕੇ ਰੁਜ਼ਗਾਰ ਦੇ ਮੌਕੇ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਯਤਨਸ਼ੀਲ ਹੋਣਾ। * ਦੂਜਿਆਂ ਦੀ ਨਕਲ ਕਰ ਕੇ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਜਾਣ ਦੀ ਹੋੜ ਤੋਂ ਬਚਣ ਦੀ ਪ੍ਰੇਰਨਾ ਦਾ ਵਿਕਾਸ। ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes) ਸਮਝ ਦੀ ਪਰਖ (ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ ਉੱਤੇ ਆਧਾਰਿਤ)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ae266512-8a02-4530-a4cc-ca5c7f6b27d2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$(Think & Express) A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ੁਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਓ— (ੳ) ਤੁਸੀਂ ਕੀ ਸੋਚਦੇ ਹੋ - ਵਿਦੇਸ਼ ਜਾਣਾ ਹਮੇਸ਼ਾ ਹੀ ਚੰਗਾ ਹੈ ਜਾਂ ਸਥਾਨਕ ਮੌਕੇ ਵੀ ਮਹੱਤਵਪੂਰਨ ਹਨ? ਆਪਣੀ ਰਾਏ ਦੱਸੋ। ਨਜ਼ਰੀਆ - ਸੋਚ/ਵਿਚਾਰਧਾਰਾ (perspective)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('da60813b-4faf-4b3e-8b74-05df5125429d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਨਾਮ ਕੌਰ (ਖੁਸ਼ੀ ਵਿੱਚ) - ਮੈਂ ਸਦਕੇ ਆਪਣੇ ਪੁੱਤ ਦੀ ਸੋਚ ਦੇ। ਮੈਂ ਤਾਂ ਤੇਰੇ ਵਿਦੇਸ਼ ਜਾਣ ਬਾਰੇ ਸੋਚ ਕੇ ਰੋਜ਼ ਸੋਚਦੀ ਰਹਿੰਦੀ ਸੀ ਕਿ ਤੇਰਾ ਵਿਯੋਗ ਕਿਵੇਂ ਝੱਲਿਆ ਕਰਾਂਗੀ। ਸ਼ਾਬਾਸ਼! ਮੇਰਾ ਸੋਹਣਾ ਪੁੱਤਰ। ਮੈਂ ਹੁਣੇ ਤੇਰੇ ਲਈ ਚੂਰੀ ਕੁੱਟ ਕੇ ਲਿਆਉਂਦੀ ਹਾਂ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('ae902afd-88a6-404e-9b3e-6fec16bb8665', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$(ਗੁਰਮੁਖ ਸਿੰਘ ਅਤੇ ਹਰਨਾਮ ਕੌਰ ਅੱਖਾਂ ਪੂੰਝਦੇ ਲਵਪ੍ਰੀਤ ਨੂੰ ਘੁੱਟ ਕੇ ਜੱਫੀ ਪਾ ਲੈਂਦੇ ਹਨ। ਦ੍ਰਿਸ਼ 4. ਅੰਤ - ਸਮਝੌਤਾ ਤੇ ਇਕੱਠ (ਦੋਸਤ ਇਕੱਠੇ ਹੋ ਕੇ ਸਮਝਦੇ ਹਨ ਕਿ ਦੋਹਾਂ ਵਿਚਾਰਾਂ ਵਿੱਚ ਸੱਚਾਈ ਹੈ। ਵਿਦੇਸ਼ ਜਾਣ ਦੇ ਸੁਪਨੇ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਵੀ ਤਰੱਕੀ ਦੇ ਮੌਕੇ ਹਨ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('dd3dd459-6507-42b2-96c6-fd7f26f94256', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਲਵਪ੍ਰੀਤ — ਮਨਕੀਰਤ ਤੂੰ ਸਹੀ ਕਹਿੰਦਾ ਸੀ ਯਾਰ, ਆਪਣੇ ਮੁਲਕ ਵਿੱਚ ਵੀ ਸਭ ਕੁਝ ਹੈ। ਬੱਸ ਨਜ਼ਰੀਆ ਬਦਲਣ ਦੀ ਲੋੜ ਹੈ। ਵਿਦੇਸ਼ ਜਾਣ ਦੀ ਦੌੜ ਨੇ ਮੈਨੂੰ ਕੀਲ ਲਿਆ ਸੀ। ਮਨਕੀਰਤ - ਲਵਪ੍ਰੀਤ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਭਵਿੱਖ ਬਣਾਉਣਾ ਮਾੜਾ ਨਹੀਂ, ਪਰ ਉਦੋਂ ਜਦੋਂ ਇੱਥੇ ਸਾਰੇ ਸਾਧਨ ਮੁੱਕ ਜਾਣ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('3ab3ac81-a5c8-4f3e-9d12-54016375f907', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਆਖਰਕਾਰ ਮਿੱਟੀ ਨਾਲ ਜੁੜੇ ਰਹਿਣਾ ਵੀ ਲਾਜ਼ਮੀ ਹੈ। ਲਵਪ੍ਰੀਤ - ਧੰਨਵਾਦ ਮਨਕੀਰਤ, ਤੇਰੇ ਕੀਤੇ ਉੱਦਮ ਨੇ ਮੇਰਾ ਨਜ਼ਰੀਆ ਬਦਲ ਦਿੱਤਾ। (ਪਰਦਾ ਡਿੱਗਦਾ ਹੈ। ਸਾਰੇ ਦੋਸਤ ਖੁਸ਼ੀ-ਖੁਸ਼ੀ ਗੱਲਾਂ ਕਰਦੇ ਹਨ। * ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਰਹਿ ਕੇ ਰੁਜ਼ਗਾਰ ਦੇ ਮੌਕੇ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਯਤਨਸ਼ੀਲ ਹੋਣਾ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('0f8e58f3-567e-4b08-8138-4262e41d1449', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$* ਦੂਜਿਆਂ ਦੀ ਨਕਲ ਕਰ ਕੇ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਜਾਣ ਦੀ ਹੋੜ ਤੋਂ ਬਚਣ ਦੀ ਪ੍ਰੇਰਨਾ ਦਾ ਵਿਕਾਸ। ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes) ਸਮਝ ਦੀ ਪਰਖ (ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ ਉੱਤੇ ਆਧਾਰਿਤ) (Think & Express) A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ੁਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਓ— (ੳ) ਤੁਸੀਂ ਕੀ ਸੋਚਦੇ ਹੋ - ਵਿਦੇਸ਼ ਜਾਣਾ ਹਮੇਸ਼ਾ ਹੀ ਚੰਗਾ ਹੈ ਜਾਂ ਸਥਾਨਕ ਮੌਕੇ ਵੀ ਮਹੱਤਵਪੂਰਨ ਹਨ? ਆਪਣੀ ਰਾਏ ਦੱਸੋ। ਨਜ਼ਰੀਆ - ਸੋਚ/ਵਿਚਾਰਧਾਰਾ (perspective)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('97317fe1-7b11-4cf4-85c0-053356dc287e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਨਾਮ ਕੌਰ (ਖੁਸ਼ੀ ਵਿੱਚ) - ਮੈਂ ਸਦਕੇ ਆਪਣੇ ਪੁੱਤ ਦੀ ਸੋਚ ਦੇ। ਮੈਂ ਤਾਂ ਤੇਰੇ ਵਿਦੇਸ਼ ਜਾਣ ਬਾਰੇ ਸੋਚ ਕੇ ਰੋਜ਼ ਸੋਚਦੀ ਰਹਿੰਦੀ ਸੀ ਕਿ ਤੇਰਾ ਵਿਯੋਗ ਕਿਵੇਂ ਝੱਲਿਆ ਕਰਾਂਗੀ। ਸ਼ਾਬਾਸ਼! ਮੇਰਾ ਸੋਹਣਾ ਪੁੱਤਰ। ਮੈਂ ਹੁਣੇ ਤੇਰੇ ਲਈ ਚੂਰੀ ਕੁੱਟ ਕੇ ਲਿਆਉਂਦੀ ਹਾਂ। (ਗੁਰਮੁਖ ਸਿੰਘ ਅਤੇ ਹਰਨਾਮ ਕੌਰ ਅੱਖਾਂ ਪੂੰਝਦੇ ਲਵਪ੍ਰੀਤ ਨੂੰ ਘੁੱਟ ਕੇ ਜੱਫੀ ਪਾ ਲੈਂਦੇ ਹਨ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('dc4ff756-be6e-4ea9-970a-59a74f0263af', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦ੍ਰਿਸ਼ 4. ਅੰਤ - ਸਮਝੌਤਾ ਤੇ ਇਕੱਠ (ਦੋਸਤ ਇਕੱਠੇ ਹੋ ਕੇ ਸਮਝਦੇ ਹਨ ਕਿ ਦੋਹਾਂ ਵਿਚਾਰਾਂ ਵਿੱਚ ਸੱਚਾਈ ਹੈ। ਵਿਦੇਸ਼ ਜਾਣ ਦੇ ਸੁਪਨੇ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਵੀ ਤਰੱਕੀ ਦੇ ਮੌਕੇ ਹਨ। ਲਵਪ੍ਰੀਤ — ਮਨਕੀਰਤ ਤੂੰ ਸਹੀ ਕਹਿੰਦਾ ਸੀ ਯਾਰ, ਆਪਣੇ ਮੁਲਕ ਵਿੱਚ ਵੀ ਸਭ ਕੁਝ ਹੈ। ਬੱਸ ਨਜ਼ਰੀਆ ਬਦਲਣ ਦੀ ਲੋੜ ਹੈ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('70c79136-1cbb-44da-8bf8-8c87a5252c39', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਵਿਦੇਸ਼ ਜਾਣ ਦੀ ਦੌੜ ਨੇ ਮੈਨੂੰ ਕੀਲ ਲਿਆ ਸੀ। ਮਨਕੀਰਤ - ਲਵਪ੍ਰੀਤ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਭਵਿੱਖ ਬਣਾਉਣਾ ਮਾੜਾ ਨਹੀਂ, ਪਰ ਉਦੋਂ ਜਦੋਂ ਇੱਥੇ ਸਾਰੇ ਸਾਧਨ ਮੁੱਕ ਜਾਣ। ਆਖਰਕਾਰ ਮਿੱਟੀ ਨਾਲ ਜੁੜੇ ਰਹਿਣਾ ਵੀ ਲਾਜ਼ਮੀ ਹੈ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
