  ('e3722d25-d446-4a45-8286-2722e3497d5f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮੈਂ ਹੁਣੇ ਤੇਰੇ ਲਈ ਚੂਰੀ ਕੁੱਟ ਕੇ ਲਿਆਉਂਦੀ ਹਾਂ। (ਗੁਰਮੁਖ ਸਿੰਘ ਅਤੇ ਹਰਨਾਮ ਕੌਰ ਅੱਖਾਂ ਪੂੰਝਦੇ ਲਵਪ੍ਰੀਤ ਨੂੰ ਘੁੱਟ ਕੇ ਜੱਫੀ ਪਾ ਲੈਂਦੇ ਹਨ। ਦ੍ਰਿਸ਼ 4. ਅੰਤ - ਸਮਝੌਤਾ ਤੇ ਇਕੱਠ)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('008ca0c1-6439-4195-8616-5dab4a1ae495', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$(ਦੋਸਤ ਇਕੱਠੇ ਹੋ ਕੇ ਸਮਝਦੇ ਹਨ ਕਿ ਦੋਹਾਂ ਵਿਚਾਰਾਂ ਵਿੱਚ ਸੱਚਾਈ ਹੈ। ਵਿਦੇਸ਼ ਜਾਣ ਦੇ ਸੁਪਨੇ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਵੀ ਤਰੱਕੀ ਦੇ ਮੌਕੇ ਹਨ। ਲਵਪ੍ਰੀਤ — ਮਨਕੀਰਤ ਤੂੰ ਸਹੀ ਕਹਿੰਦਾ ਸੀ ਯਾਰ, ਆਪਣੇ ਮੁਲਕ ਵਿੱਚ ਵੀ ਸਭ ਕੁਝ ਹੈ। ਬੱਸ ਨਜ਼ਰੀਆ ਬਦਲਣ ਦੀ ਲੋੜ ਹੈ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('6ef83f8f-8bad-4d70-95a9-49d20619da40', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਵਿਦੇਸ਼ ਜਾਣ ਦੀ ਦੌੜ ਨੇ ਮੈਨੂੰ ਕੀਲ ਲਿਆ ਸੀ। ਮਨਕੀਰਤ - ਲਵਪ੍ਰੀਤ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਭਵਿੱਖ ਬਣਾਉਣਾ ਮਾੜਾ ਨਹੀਂ, ਪਰ ਉਦੋਂ ਜਦੋਂ ਇੱਥੇ ਸਾਰੇ ਸਾਧਨ ਮੁੱਕ ਜਾਣ। ਆਖਰਕਾਰ ਮਿੱਟੀ ਨਾਲ ਜੁੜੇ ਰਹਿਣਾ ਵੀ ਲਾਜ਼ਮੀ ਹੈ। ਲਵਪ੍ਰੀਤ - ਧੰਨਵਾਦ ਮਨਕੀਰਤ, ਤੇਰੇ ਕੀਤੇ ਉੱਦਮ ਨੇ ਮੇਰਾ ਨਜ਼ਰੀਆ ਬਦਲ ਦਿੱਤਾ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('a05151ac-37f1-4be6-bab1-34cca29332ac', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$(ਪਰਦਾ ਡਿੱਗਦਾ ਹੈ। ਸਾਰੇ ਦੋਸਤ ਖੁਸ਼ੀ-ਖੁਸ਼ੀ ਗੱਲਾਂ ਕਰਦੇ ਹਨ। * ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਰਹਿ ਕੇ ਰੁਜ਼ਗਾਰ ਦੇ ਮੌਕੇ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਯਤਨਸ਼ੀਲ ਹੋਣਾ। * ਦੂਜਿਆਂ ਦੀ ਨਕਲ ਕਰ ਕੇ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਜਾਣ ਦੀ ਹੋੜ ਤੋਂ ਬਚਣ ਦੀ ਪ੍ਰੇਰਨਾ ਦਾ ਵਿਕਾਸ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('32e70db7-d97a-4424-8d35-00b12adfa23e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਸਿੱਖਣ ਨਤੀਜੇ (Learning Outcomes) ਸਮਝ ਦੀ ਪਰਖ (ਨਵੀਂ ਰਾਸ਼ਟਰੀ ਸਿੱਖਿਆ ਨੀਤੀ (N.E.P.) ਅਤੇ ਰਾਸ਼ਟਰੀ ਪਾਠਕ੍ਰਮ ਫਰੇਮਵਰਕ (N.C.F.) ਦੇ ਨਿਰਦੇਸ਼ਾਂ ਉੱਤੇ ਆਧਾਰਿਤ) (Think & Express) A. ਹੇਠਾਂ ਲਿਖੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਜ਼ੁਬਾਨੀ ਰੂਪ ਵਿੱਚ ਦਿਓ— (ੳ) ਤੁਸੀਂ ਕੀ ਸੋਚਦੇ ਹੋ - ਵਿਦੇਸ਼ ਜਾਣਾ ਹਮੇਸ਼ਾ ਹੀ ਚੰਗਾ ਹੈ ਜਾਂ ਸਥਾਨਕ ਮੌਕੇ ਵੀ ਮਹੱਤਵਪੂਰਨ ਹਨ? ਆਪਣੀ ਰਾਏ ਦੱਸੋ। ਨਜ਼ਰੀਆ - ਸੋਚ/ਵਿਚਾਰਧਾਰਾ (perspective)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('eecd37f7-298d-4384-ab5e-becbd79fa276', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਹਰਨਾਮ ਕੌਰ (ਖੁਸ਼ੀ ਵਿੱਚ) - ਮੈਂ ਸਦਕੇ ਆਪਣੇ ਪੁੱਤ ਦੀ ਸੋਚ ਦੇ। ਮੈਂ ਤਾਂ ਤੇਰੇ ਵਿਦੇਸ਼ ਜਾਣ ਬਾਰੇ ਸੋਚ ਕੇ ਰੋਜ਼ ਸੋਚਦੀ ਰਹਿੰਦੀ ਸੀ ਕਿ ਤੇਰਾ ਵਿਯੋਗ ਕਿਵੇਂ ਝੱਲਿਆ ਕਰਾਂਗੀ। ਸ਼ਾਬਾਸ਼! ਮੇਰਾ ਸੋਹਣਾ ਪੁੱਤਰ। ਮੈਂ ਹੁਣੇ ਤੇਰੇ ਲਈ ਚੂਰੀ ਕੁੱਟ ਕੇ ਲਿਆਉਂਦੀ ਹਾਂ। (ਗੁਰਮੁਖ ਸਿੰਘ ਅਤੇ ਹਰਨਾਮ ਕੌਰ ਅੱਖਾਂ ਪੂੰਝਦੇ ਲਵਪ੍ਰੀਤ ਨੂੰ ਘੁੱਟ ਕੇ ਜੱਫੀ ਪਾ ਲੈਂਦੇ ਹਨ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('3863dd8c-3a9a-4d6e-9774-8ac0f58fb608', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਦ੍ਰਿਸ਼ 4. ਅੰਤ - ਸਮਝੌਤਾ ਤੇ ਇਕੱਠ (ਦੋਸਤ ਇਕੱਠੇ ਹੋ ਕੇ ਸਮਝਦੇ ਹਨ ਕਿ ਦੋਹਾਂ ਵਿਚਾਰਾਂ ਵਿੱਚ ਸੱਚਾਈ ਹੈ। ਵਿਦੇਸ਼ ਜਾਣ ਦੇ ਸੁਪਨੇ ਦੇ ਨਾਲ-ਨਾਲ ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਵੀ ਤਰੱਕੀ ਦੇ ਮੌਕੇ ਹਨ। ਲਵਪ੍ਰੀਤ — ਮਨਕੀਰਤ ਤੂੰ ਸਹੀ ਕਹਿੰਦਾ ਸੀ ਯਾਰ, ਆਪਣੇ ਮੁਲਕ ਵਿੱਚ ਵੀ ਸਭ ਕੁਝ ਹੈ। ਬੱਸ ਨਜ਼ਰੀਆ ਬਦਲਣ ਦੀ ਲੋੜ ਹੈ। ਵਿਦੇਸ਼ ਜਾਣ ਦੀ ਦੌੜ ਨੇ ਮੈਨੂੰ ਕੀਲ ਲਿਆ ਸੀ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL),
  ('b1fedffe-2e6d-46d3-98d6-6809a8134aaa', '8af718c6-ca11-482b-9d6b-832f2b767928', 'a98a8046-a655-4fbc-8679-a30d1ce234f6', '07d40414-eeaf-4ee4-9400-8469ee87262e', 'cf2d9caa-5ae4-46df-9954-b637993032da', '95b8bc81-1f6b-4a5c-845b-a3afb375fa3a', $qbx$ਮਨਕੀਰਤ - ਲਵਪ੍ਰੀਤ ਵਿਦੇਸ਼ ਜਾ ਕੇ ਭਵਿੱਖ ਬਣਾਉਣਾ ਮਾੜਾ ਨਹੀਂ, ਪਰ ਉਦੋਂ ਜਦੋਂ ਇੱਥੇ ਸਾਰੇ ਸਾਧਨ ਮੁੱਕ ਜਾਣ। ਆਖਰਕਾਰ ਮਿੱਟੀ ਨਾਲ ਜੁੜੇ ਰਹਿਣਾ ਵੀ ਲਾਜ਼ਮੀ ਹੈ। ਲਵਪ੍ਰੀਤ - ਧੰਨਵਾਦ ਮਨਕੀਰਤ, ਤੇਰੇ ਕੀਤੇ ਉੱਦਮ ਨੇ ਮੇਰਾ ਨਜ਼ਰੀਆ ਬਦਲ ਦਿੱਤਾ। (ਪਰਦਾ ਡਿੱਗਦਾ ਹੈ। ਸਾਰੇ ਦੋਸਤ ਖੁਸ਼ੀ-ਖੁਸ਼ੀ ਗੱਲਾਂ ਕਰਦੇ ਹਨ। * ਆਪਣੇ ਦੇਸ਼ ਵਿੱਚ ਰਹਿ ਕੇ ਰੁਜ਼ਗਾਰ ਦੇ ਮੌਕੇ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਯਤਨਸ਼ੀਲ ਹੋਣਾ। * ਦੂਜਿਆਂ ਦੀ ਨਕਲ ਕਰ ਕੇ ਵਿਦੇਸ਼ਾਂ ਵਿੱਚ ਜਾਣ ਦੀ ਹੋੜ ਤੋਂ ਬਚਣ ਦੀ ਪ੍ਰੇਰਨਾ ਦਾ ਵਿਕਾਸ।)$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-30T06-17-57-421Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 5, NULL);
